'))])),_Card(title:'قیمت',child:Row(children:[Expanded(child:TextField(controller:regular,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'قیمت اصلی'))),const SizedBox(width:10),Expanded(child:TextField(controller:sale,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'قیمت فروش ویژه')))])),_Card(title:'موجودی',child:Column(children:[SwitchListTile(contentPadding:EdgeInsets.zero,value:manageStock,onChanged:(v)=>setState(()=>manageStock=v),title:const Text('مدیریت موجودی')),if(manageStock)TextField(controller:stock,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'تعداد موجودی')),DropdownButtonFormField<String>(value:stockStatus,decoration:const InputDecoration(labelText:'وضعیت موجودی'),items:const [DropdownMenuItem(value:'instock',child:Text('موجود')),DropdownMenuItem(value:'outofstock',child:Text('ناموجود')),DropdownMenuItem(value:'onbackorder',child:Text('پیش‌خرید'))],onChanged:(v)=>setState(()=>stockStatus=v!))])),if(attributes.isNotEmpty)_Card(title:'ویژگی‌ها',child:Column(children:attributes.map((raw){final a=Map<String,dynamic>.from(raw as Map);return ListTile(contentPadding:EdgeInsets.zero,title:Text('${a['name']}'),subtitle:Text((a['options'] as List? ?? const []).join('، ')));}).toList())),if(variations.isNotEmpty)_Card(title:'متغیرها (${variations.length})',child:Column(children:variations.map((raw){final v=Map<String,dynamic>.from(raw as Map);return ListTile(onTap:_saving?null:()=>_editVariation(v),contentPadding:EdgeInsets.zero,title:Text((v['attributes'] as Map? ?? const {}).values.join(' / ')),subtitle:Text('${v['price']}  •  ${v['stock_quantity']??v['stock_status']}'),trailing:const Icon(Icons.edit_outlined));}).toList()))]);}));
}
class _Card extends StatelessWidget{const _Card({required this.title,required this.child});final String title;final Widget child;@override Widget build(BuildContext context)=>Card(margin:const EdgeInsets.only(bottom:12),child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(title,style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const SizedBox(height:12),child])));}
